WITH input AS (SELECT jsonb_array_elements('[{"id":"YE22","description":"محافظة شمالية حدودية، تشتهر بمدينة صعدة القديمة وبساتينها وامتدادها الجبلي والصحراوي.\n\nصعدة محافظة شمالية حدودية تتداخل فيها المدينة التاريخية والوديان الزراعية والجبال والمناطق الأكثر جفافاً. تتفاوت طبيعة مديرياتها بصورة واضحة، لذلك من الضروري عدم تعميم خصائص مركز صعدة على المساحة الحدودية كلها.","old_description":"محافظة شمالية حدودية، تشتهر بمدينة صعدة القديمة وبساتينها وامتدادها الجبلي والصحراوي.","history":"كانت صعدة مركزاً علمياً وتجارياً مهماً في شمال اليمن، وتضم تراثاً عمرانياً ودينياً قديماً.\n\nارتبطت المدينة القديمة بمراكز علمية ودينية وأسواق شمال اليمن. ويُدرس جامع الهادي والتراث العمراني ضمن سياق تطور المؤسسات والمجتمعات المحلية، مع تجنب الخلط بين التاريخ الموثق والروايات الشفوية أو أحداث النزاع الحديث.","old_history":"كانت صعدة مركزاً علمياً وتجارياً مهماً في شمال اليمن، وتضم تراثاً عمرانياً ودينياً قديماً.","geography":"تتكون من أحواض زراعية وجبال وأودية ومناطق صحراوية تقترب من الحدود الشمالية.\n\nتفسر الجبال والأحواض والأودية اختلاف الزراعة والغطاء النباتي والحرارة عبر المحافظة. وتختلف احتياجات المياه والطرق في الوديان المزروعة عن المناطق الجبلية البعيدة، ما يحد من فائدة المتوسط الجغرافي العام.","old_geography":"تتكون من أحواض زراعية وجبال وأودية ومناطق صحراوية تقترب من الحدود الشمالية.","economy":"تشمل الأنشطة الزراعة والتجارة والرعي والحرف والأسواق المحلية.\n\nتتصل الأنشطة الزراعية والرعوية بالتجارة والأسواق المحلية، لكن حجم الإنتاج وفرص العمل لا يمكن تقديرهما من وصف القطاعات. وتتغير ظروف الحركة والخدمات بمرور الوقت، لذلك ينبغي تجنب تقديم معلومات تشغيلية غير محدثة.","old_economy":"تشمل الأنشطة الزراعة والتجارة والرعي والحرف والأسواق المحلية.","landmarks":"مدينة صعدة القديمة، جامع الهادي، جبل مران، رازح والبساتين المحيطة بالمدينة.\n\nتبرز مدينة صعدة القديمة وجامع الهادي والبساتين ومناطق رازح وجبل مران نقاطاً لفهم العمارة والتضاريس والاستقرار في شمال اليمن. وجود الموقع في الدليل لا يدل على سلامة الوصول إليه أو جاهزيته للزيارة.","old_landmarks":"مدينة صعدة القديمة، جامع الهادي، جبل مران، رازح والبساتين المحيطة بالمدينة."},{"id":"YE23","description":"محافظة تحيط بأمانة العاصمة وتضم مرتفعات وأودية وقرى زراعية ومواقع طبيعية وتاريخية.\n\nمحافظة صنعاء تحيط بأمانة العاصمة لكنها ليست جزءاً من وحدتها الحضرية المستقلة. وتتوزع بلداتها وقراها بين جبال وهضاب وقيعان، بما يجعل المحافظة مغايرة لمدينة صنعاء القديمة التي تقع إدارياً ضمن الأمانة.","old_description":"محافظة تحيط بأمانة العاصمة وتضم مرتفعات وأودية وقرى زراعية ومواقع طبيعية وتاريخية.","history":"تنتشر فيها قرى وحصون قديمة ارتبطت بصنعاء وطرق القوافل إلى بقية مناطق اليمن.\n\nتكشف القرى القديمة والحصون ومسارات القوافل عن تاريخ مرتبط بمركز صنعاء وبالتبادل مع الأقاليم اليمنية الأخرى. ويستدعي سرد تاريخ المحافظة التمييز بين الضواحي والبلدات الجبلية وبين تاريخ المدينة الواقعة خارج حدودها الإدارية.","old_history":"تنتشر فيها قرى وحصون قديمة ارتبطت بصنعاء وطرق القوافل إلى بقية مناطق اليمن.","geography":"تغلب عليها الهضاب والجبال والأودية والقيعان المرتفعة، ويتسم مناخها بالاعتدال نهاراً والبرودة ليلاً.\n\nتمتد المرتفعات والأودية والقيعان حول الحوض الحضري، وتتباين فرص الزراعة وتجمع المياه بحسب تضاريس كل مديرية. وليس صحيحاً اعتبار كل مناطق المحافظة على الارتفاع نفسه أو ذات المناخ الحضري ذاته.","old_geography":"تغلب عليها الهضاب والجبال والأودية والقيعان المرتفعة، ويتسم مناخها بالاعتدال نهاراً والبرودة ليلاً.","economy":"تعتمد على الزراعة والرعي والتجارة والخدمات والصناعات والحرف المحلية.\n\nتقوم سبل العيش على الزراعة والرعي والتجارة والخدمات والحرف، وقد تتأثر ببعد القرية عن الأسواق والطرق المؤدية إلى العاصمة. ولا يمكن تحديد متوسط دخل أو حجم إنتاج من خريطة المواقع وحدها.","old_economy":"تعتمد على الزراعة والرعي والتجارة والخدمات والصناعات والحرف المحلية.","landmarks":"دار الحجر، وادي ظهر، شبام الغراس، مناخة، الحيمة وقرى المرتفعات.\n\nيقدم وادي ظهر ودار الحجر ومناخة والحيمة وقرى المرتفعات مداخل متنوعة لدراسة العمارة الريفية والطبيعة والتاريخ. ويجب الانتباه إلى أن صنعاء القديمة وباب اليمن من معالم أمانة العاصمة لا هذه المحافظة.","old_landmarks":"دار الحجر، وادي ظهر، شبام الغراس، مناخة، الحيمة وقرى المرتفعات."},{"id":"YE24","description":"مدينة ومحافظة ساحلية ذات ميناء طبيعي ومكانة اقتصادية وثقافية بارزة على خليج عدن.\n\nتتميز عدن بأنها محافظة حضرية ساحلية تقوم على ميناء طبيعي وخلجان وأحياء ارتبط نموها بالتجارة البحرية. وهي تختلف في امتدادها العمراني والجغرافي عن المحافظات الريفية الواسعة؛ لذلك يلزم التعامل مع أرقام مساحتها وسكانها بوصفها بيانات حضرية.","old_description":"مدينة ومحافظة ساحلية ذات ميناء طبيعي ومكانة اقتصادية وثقافية بارزة على خليج عدن.","history":"ازدهرت عدن كميناء دولي عبر قرون، وتعاقبت عليها مراحل تجارية وسياسية تركت طابعاً عمرانياً متنوعاً.\n\nتداخلت في عدن فترات من التجارة البحرية والحكم المحلي والاستعماري والتحولات السياسية الحديثة، وأثرت تلك المراحل في الميناء والأحياء التاريخية والمباني العامة. ويُنصح بالفصل بين التاريخ التجاري للمدينة والحالة التشغيلية المعاصرة للمنشآت.","old_history":"ازدهرت عدن كميناء دولي عبر قرون، وتعاقبت عليها مراحل تجارية وسياسية تركت طابعاً عمرانياً متنوعاً.","geography":"تقع على شبه جزيرة بركانية وتحيط بها سواحل وخلجان، ويغلب عليها المناخ الحار قليل الأمطار.\n\nتجمع شبه الجزيرة البركانية والمياه الساحلية مشهداً جغرافياً يفسر مواقع بعض الأحياء والمرافئ والطرق القديمة. ويختلف مناخها الحار وقلة أمطارها عن مناخ المرتفعات اليمنية؛ كما تختلف أحياء كريتر والتواهي في علاقتها بالبحر.","old_geography":"تقع على شبه جزيرة بركانية وتحيط بها سواحل وخلجان، ويغلب عليها المناخ الحار قليل الأمطار.","economy":"يرتكز نشاطها على الميناء والتجارة والخدمات والنقل والصناعة والسياحة الساحلية.\n\nترتبط الأنشطة التجارية واللوجستية والخدمية بالصناعة والنقل عبر الميناء والمدينة. لكن المكانة التاريخية لميناء عدن لا توفر رقماً موثوقاً عن حجمه الحالي أو نشاطه أثناء النزاع؛ ويجب الاستناد إلى تقارير تشغيل حديثة لتقدير ذلك.","old_economy":"يرتكز نشاطها على الميناء والتجارة والخدمات والنقل والصناعة والسياحة الساحلية.","landmarks":"صهاريج عدن، قلعة صيرة، منارة عدن، شاطئ جولدمور، كريتر والتواهي.\n\nتسمح قلعة صيرة والصهاريج وكريتر والتواهي ومنارة عدن بفهم العلاقة بين الدفاع والمياه والعمران والملاحة. ولا ينبغي مساواة الأهمية التاريخية بتوافر مرافق الزيارة أو حفظ المباني في الوقت الراهن.","old_landmarks":"صهاريج عدن، قلعة صيرة، منارة عدن، شاطئ جولدمور، كريتر والتواهي."},{"id":"YE25","description":"محافظة جنوبية تمتد من السواحل والسهول القريبة من عدن إلى الجبال والوديان الداخلية.\n\nتقع لحج في نطاق جنوبي متنوع يصل السهول والوديان الزراعية القريبة من عدن بالمرتفعات الداخلية والمناطق الساحلية. هذا الامتداد يفسر اختلاف أنماط العمل والسكن بين الحوطة ومديريات أبعد شمالاً أو غرباً.","old_description":"محافظة جنوبية تمتد من السواحل والسهول القريبة من عدن إلى الجبال والوديان الداخلية.","history":"عرفت لحج بدورها الزراعي والثقافي، وكانت الحوطة مركزاً لسلطنة لحج في التاريخ الحديث.\n\nتُذكر الحوطة في تاريخ سلطنة لحج الحديث، وتظهر المنطقة أيضاً في تراث الزراعة والعمارة والفنون المحلية. ويحتاج عرض أي أحداث سياسية أو تواريخ محددة إلى مراجع مستقلة تفصل بين المراحل التاريخية المتعاقبة.","old_history":"عرفت لحج بدورها الزراعي والثقافي، وكانت الحوطة مركزاً لسلطنة لحج في التاريخ الحديث.","geography":"تضم دلتا تبن والسهول الزراعية ومناطق ساحلية وجبلية تتدرج شمالاً.\n\nتغذي الأودية بعض السهول، وفي مقدمتها دلتا تبن، فيما تتدرج التضاريس نحو مناطق جبلية ومرتفعات تختلف في المناخ والاستخدام الزراعي. لذلك لا تُقرأ الموارد المائية أو الزراعية باعتبارها موزعة بالتساوي داخل المحافظة.","old_geography":"تضم دلتا تبن والسهول الزراعية ومناطق ساحلية وجبلية تتدرج شمالاً.","economy":"تشمل أنشطتها الزراعة وصيد الأسماك والرعي والتجارة والخدمات.\n\nتشكل الزراعة والتجارة والخدمات والرعي والصيد مصادر دخل متنوعة بحسب المنطقة. وتعتمد صلات السوق أيضاً على قرب بعض المديريات من عدن، لكن ذلك لا يعني وجود تقدير مؤكد للدخل أو حركة النقل الحالية.","old_economy":"تشمل أنشطتها الزراعة وصيد الأسماك والرعي والتجارة والخدمات.","landmarks":"الحوطة، وادي تبن، العند، طور الباحة، رأس العارة والمناطق الساحلية.\n\nيمكن تنظيم قراءة المكان حول الحوطة ووادي تبن والعند وطور الباحة ورأس العارة لفهم الواجهات الزراعية والبرية والساحلية للمحافظة. ذكر المواقع ليس توصية سفر ولا توثيقاً لظروف الوصول الآنية.","old_landmarks":"الحوطة، وادي تبن، العند، طور الباحة، رأس العارة والمناطق الساحلية."},{"id":"YE26","description":"محافظة شرقي صنعاء ذات أهمية تاريخية واقتصادية، وترتبط باسم مملكة سبأ وسد مأرب.\n\nتجمع مأرب بين شهرة تاريخية مرتبطة بمملكة سبأ وبين حضور اقتصادي وزراعي معاصر. ويتفاوت مشهد المحافظة بين مناطق صحراوية وأودية ومراكز حضرية ومرتفعات غربية، فلا يصح اختزالها في السد التاريخي وحده.","old_description":"محافظة شرقي صنعاء ذات أهمية تاريخية واقتصادية، وترتبط باسم مملكة سبأ وسد مأرب.","history":"كانت مأرب مركزاً لمملكة سبأ، وتضم معابد ونقوشاً ومنشآت ري تعكس تاريخاً حضارياً عريقاً.\n\nتضم مأرب مواقع مملكة سبأ، بما فيها منشآت الري والمعابد والنقوش التي تعكس تطور التنظيم السياسي والعمراني القديم. أدرجت اليونسكو «معالم مملكة سبأ القديمة، مأرب» في قائمة التراث العالمي عام 2023، وهو توصيف لمواقع محددة لا لجميع أراضي المحافظة.","old_history":"كانت مأرب مركزاً لمملكة سبأ، وتضم معابد ونقوشاً ومنشآت ري تعكس تاريخاً حضارياً عريقاً.","geography":"تجمع بين الصحارى والأودية والمرتفعات الغربية، وتنتشر الواحات والزراعة حول مجاري المياه.\n\nتجاور الأودية والأراضي الزراعية مساحات أكثر جفافاً، وتختلف أنماط الاستقرار حول مصادر المياه والطرق. ويساعد هذا التدرج على فهم أهمية أنظمة الري التاريخية والحديثة دون افتراض استمرار وظائفها بالشكل نفسه.","old_geography":"تجمع بين الصحارى والأودية والمرتفعات الغربية، وتنتشر الواحات والزراعة حول مجاري المياه.","economy":"يرتكز اقتصادها على النفط والغاز والطاقة والزراعة والتجارة والخدمات.\n\nيشمل اقتصاد مأرب موارد الطاقة والزراعة والتجارة والخدمات، لكن حجم أي قطاع يتغير بحسب السنوات وطرق القياس. ولا يصح عرض تقديرات للنفط والغاز أو أعداد العاملين من دون تقارير مستقلة وحديثة.","old_economy":"يرتكز اقتصادها على النفط والغاز والطاقة والزراعة والتجارة والخدمات.","landmarks":"سد مأرب، عرش بلقيس، محرم بلقيس، صرواح، مدينة مأرب القديمة.\n\nتشكّل المعابد التاريخية ومدينة مأرب القديمة وصرواح والسد نقاطاً متكاملة لدراسة مملكة سبأ وإدارة المياه والعمران. والتمييز بين السد الأثري والمنشآت المعاصرة ضروري حتى لا تختلط فترات البناء ووظائفها.","old_landmarks":"سد مأرب، عرش بلقيس، محرم بلقيس، صرواح، مدينة مأرب القديمة."},{"id":"YE27","description":"محافظة جبلية غربي صنعاء، معروفة بمدرجاتها الزراعية وقراها المبنية على القمم والمنحدرات.\n\nتقع المحويت في منطقة جبلية غربي صنعاء ذات قرى ومدرجات وبلدات على قمم ومنحدرات. يساعد هذا الطابع على تفسير تباعد بعض التجمعات وصعوبة تعميم خصائص المناخ والنقل على المحافظة كلها.","old_description":"محافظة جبلية غربي صنعاء، معروفة بمدرجاتها الزراعية وقراها المبنية على القمم والمنحدرات.","history":"نشأت تجمعاتها حول الحصون والقرى الجبلية وطرق التجارة بين المرتفعات وسهل تهامة.\n\nتظهر البلدات المحصنة والقرى الجبلية ضمن تاريخ طرق الانتقال بين المرتفعات وتهامة. وتحتاج تواريخ تشييد المباني ونسبتها إلى عصور بعينها إلى مصادر أثرية أو معمارية محددة، بعيداً عن الروايات غير الموثقة.","old_history":"نشأت تجمعاتها حول الحصون والقرى الجبلية وطرق التجارة بين المرتفعات وسهل تهامة.","geography":"تتميز بجبال شديدة الانحدار وأودية ومدرجات زراعية، ويعتدل مناخها في المناطق المرتفعة.\n\nتتنوع الارتفاعات والأودية والمدرجات داخل مساحة جبلية متدرجة، فتتباين موارد المياه والمناخ وأشكال الاستقرار. ويشرح موقع كثير من القرى على المرتفعات أهمية الطرق والوصول إلى الأراضي المزروعة.","old_geography":"تتميز بجبال شديدة الانحدار وأودية ومدرجات زراعية، ويعتدل مناخها في المناطق المرتفعة.","economy":"تتركز الأنشطة في الزراعة وتربية الماشية والأسواق المحلية والحرف التقليدية.\n\nتشكل الزراعة وتربية الماشية والتجارة المحلية والحرف جزءاً من الأنشطة التقليدية. ويمكن دراسة ارتباط أسواق المدن بمحاصيل القرى دون افتراض نسب مساهمة اقتصادية محددة في غياب إحصاءات حديثة.","old_economy":"تتركز الأنشطة في الزراعة وتربية الماشية والأسواق المحلية والحرف التقليدية.","landmarks":"مدينة المحويت، شبام كوكبان، الطويلة، الرجم والقرى والمدرجات الجبلية.\n\nتجمع مدينة المحويت والطويلة والرجم وشبام كوكبان وقرى المدرجات بين مشاهد التحصين العمراني والمنحدرات الزراعية. ينبغي استخدام أسماء المواقع لربط التاريخ بالمكان لا كمعلومات عن جودة المرافق السياحية.","old_landmarks":"مدينة المحويت، شبام كوكبان، الطويلة، الرجم والقرى والمدرجات الجبلية."},{"id":"YE28","description":"محافظة شرقية شاسعة تمتد على بحر العرب وتتميز بلغتها المهرية وتراثها المحلي الخاص.\n\nالمهرة محافظة شرقية تمتد على بحر العرب، ولها هوية ثقافية ولغوية محلية بارزة؛ فاللغة المهرية جزء مهم من تراث سكانها. يمتد طابعها الجغرافي إلى الداخل الصحراوي والجبلي، وليس ساحل الغيضة وحده.","old_description":"محافظة شرقية شاسعة تمتد على بحر العرب وتتميز بلغتها المهرية وتراثها المحلي الخاص.","history":"ارتبطت المهرة تاريخياً بطرق التجارة البحرية والبرية مع حضرموت وعُمان ومحيط المحيط الهندي.\n\nيرتبط تاريخ المهرة بالاتصال البحري والبري مع حضرموت وعمان والمحيط الهندي، وبالتقاليد المحلية المتوارثة. ولا تعني هذه الروابط اشتراك كل المجموعات في تاريخ سياسي واحد؛ ينبغي التفريق بين اللغة والثقافة والحدود الإدارية الحديثة.","old_history":"ارتبطت المهرة تاريخياً بطرق التجارة البحرية والبرية مع حضرموت وعُمان ومحيط المحيط الهندي.","geography":"تضم سواحل طويلة وصحارى وجبالاً وأودية، وتتأثر بعض مناطقها موسمياً بالرياح والأمطار.\n\nتشمل البيئة الساحل والصحارى والجبال والأودية، وتتميز منطقة حوف بغطاء نباتي يتأثر بالرياح الموسمية. وتختلف كمية الأمطار ودرجات الحرارة باختلاف الموقع، فلا يصف متوسط واحد الساحل والمناطق الداخلية.","old_geography":"تضم سواحل طويلة وصحارى وجبالاً وأودية، وتتأثر بعض مناطقها موسمياً بالرياح والأمطار.","economy":"تعتمد على الصيد والرعي والتجارة والنقل وبعض الأنشطة الزراعية والخدمية.\n\nتتداخل أنشطة الصيد والرعي والتجارة والنقل مع خدمات المدن وبعض الزراعات المحلية. من الضروري عند تحليل اقتصاد المحافظة الفصل بين النشاط التقليدي والحركة الحدودية الحديثة، دون تقدير حجمها من المشاهد العامة.","old_economy":"تعتمد على الصيد والرعي والتجارة والنقل وبعض الأنشطة الزراعية والخدمية.","landmarks":"الغيضة، حوف ومحمية حوف، نشطون، قشن، وشواطئ بحر العرب.\n\nتقدم حوف وقشن ونشطون والغيضة والواجهات الساحلية مواقع لفهم التنوع الطبيعي والثقافي في المهرة، وينبغي تقديم محمية حوف بوصفها بيئة تتطلب الصون، لا ضماناً لتوافر خدمات زيارة معينة.","old_landmarks":"الغيضة، حوف ومحمية حوف، نشطون، قشن، وشواطئ بحر العرب."},{"id":"YE29","description":"محافظة شمال صنعاء تضم سهولاً زراعية ومدناً تاريخية وامتدادات جبلية واسعة.\n\nعمران محافظة شمالية مرتفعة تضم مناطق قيعان زراعية وحواضر تاريخية وجبالاً وأودية. وتعطي صلاتها بالممرات الشمالية والمرتفعات المحيطة بصنعاء أهمية جغرافية للتبادل بين القرى والأسواق.","old_description":"محافظة شمال صنعاء تضم سهولاً زراعية ومدناً تاريخية وامتدادات جبلية واسعة.","history":"كانت عمران ومحيطها محطة مهمة على طرق القوافل، وتضم مواقع مرتبطة بتاريخ اليمن القديم والإسلامي.\n\nتتضمن المحافظة بلدات ومدناً محصنة ارتبطت بتاريخ طرق القوافل والمجتمعات الجبلية. ويمكن دراسة ثلاء وشهارة إلى جانب عمران لفهم اختلاف أشكال العمران والوظائف الدفاعية والتجارية.","old_history":"كانت عمران ومحيطها محطة مهمة على طرق القوافل، وتضم مواقع مرتبطة بتاريخ اليمن القديم والإسلامي.","geography":"تشمل قاع عمران والجبال والهضاب والأودية، مع مناخ أبرد نسبياً في المناطق المرتفعة.\n\nيتداخل قاع عمران مع الهضاب والجبال في مشهد متغير الارتفاعات، ما يؤثر في الزراعة ودرجات الحرارة والتجمعات السكنية. وتُقرأ خصائص كل مديرية على حدة قبل تعميم مناخ المرتفعات على المحافظة.","old_geography":"تشمل قاع عمران والجبال والهضاب والأودية، مع مناخ أبرد نسبياً في المناطق المرتفعة.","economy":"تعتمد على الزراعة والرعي والتجارة والصناعات المحلية ومواد البناء.\n\nتتوزع أنشطة السكان بين الزراعة والرعي والتجارة والصناعة المحلية ومواد البناء. وتختلف سبل العيش حسب القرب من الأسواق والطرق ومناطق الزراعة؛ لا يمكن اشتقاق الناتج الاقتصادي الحالي من وصف القطاعات وحده.","old_economy":"تعتمد على الزراعة والرعي والتجارة والصناعات المحلية ومواد البناء.","landmarks":"مدينة عمران القديمة، ثلاء، حوث، شهارة وجسرها التاريخي.\n\nتبرز ثلاء وشهارة وجسرها وحوث ومدينة عمران كنقاط لدراسة البنى التاريخية والاتصال بين الجبال والسهول. وتشكل حالة المباني والطرق والأمان موضوعات تحقق مستقل لا تغطيها قائمة المعالم.","old_landmarks":"مدينة عمران القديمة، ثلاء، حوث، شهارة وجسرها التاريخي."},{"id":"YE30","description":"محافظة جبلية في جنوب اليمن، تشكل ممراً بين المرتفعات الوسطى والمحافظات الجنوبية.\n\nتتكون الضالع من نطاقات جبلية وهضبية تصل مناطق جنوب اليمن بالمرتفعات الوسطى. ويؤثر اختلاف الارتفاع في عمران القرى وشبكة الطرق والأنشطة الزراعية، فلا تمثل المدينة الرئيسية جميع المديريات.","old_description":"محافظة جبلية في جنوب اليمن، تشكل ممراً بين المرتفعات الوسطى والمحافظات الجنوبية.","history":"ارتبطت مناطق الضالع تاريخياً بطرق الحركة بين الشمال والجنوب وبسلطنات وإمارات محلية.\n\nارتبطت مناطق الضالع بطرق التنقل والتبادل وبكيانات محلية تاريخية في مراحل متعددة. ولا يصح اختزال تاريخ المحافظة في الحدود الإدارية الحديثة أو في فترة سياسية واحدة دون الرجوع إلى المصادر التفصيلية.","old_history":"ارتبطت مناطق الضالع تاريخياً بطرق الحركة بين الشمال والجنوب وبسلطنات وإمارات محلية.","geography":"تغلب عليها الجبال والهضاب والأودية، مع تنوع مناخي بين المناطق المرتفعة والمنخفضة.\n\nتغلب الجبال والهضاب والأودية على التضاريس، مع مناطق متفاوتة في الارتفاع والحرارة. ويشرح ذلك اختلاف طبيعة الزراعة وتوزيع القرى، بما يتطلب دراسة الظروف المحلية بدلاً من الاعتماد على متوسط عام.","old_geography":"تغلب عليها الجبال والهضاب والأودية، مع تنوع مناخي بين المناطق المرتفعة والمنخفضة.","economy":"تنتشر فيها الزراعة المحلية وتربية الماشية والتجارة والخدمات المرتبطة بالمدن والأسواق.\n\nتجمع الأنشطة المعيشية بين الزراعة المحلية والرعي والتجارة والخدمات. ولا يمكن تقدير تغير فرص العمل أو الحركة بين المحافظات أثناء النزاع اعتماداً على هذا الوصف الجغرافي وحده.","old_economy":"تنتشر فيها الزراعة المحلية وتربية الماشية والتجارة والخدمات المرتبطة بالمدن والأسواق.","landmarks":"مدينة الضالع، دمت وحماماتها الطبيعية، جبال جحاف وعدد من القرى الجبلية.\n\nتُذكر دمت وحماماتها الطبيعية وجبال جحاف ومدن الضالع ضمن المواقع ذات الاهتمام الجغرافي والمحلي. وتتطلب أي معلومات عن حالة الحمامات أو المرافق أو سلامة المسارات تحديثاً منفصلاً.","old_landmarks":"مدينة الضالع، دمت وحماماتها الطبيعية، جبال جحاف وعدد من القرى الجبلية."},{"id":"YE31","description":"محافظة جبلية غربي اليمن، تتميز بمرتفعاتها الخضراء وقراها ومدرجاتها الزراعية.\n\nريمة محافظة جبلية تتكون من قرى ومدرجات تمتد على منحدرات متفاوتة، وتتصل بيئتها بمرتفعات غرب اليمن وطرق الانتقال نحو تهامة. تكشف هذه الطبيعة عن اختلاف الوصول والخدمات بين القرى والمراكز المحلية.","old_description":"محافظة جبلية غربي اليمن، تتميز بمرتفعاتها الخضراء وقراها ومدرجاتها الزراعية.","history":"تشكلت تجمعاتها التاريخية حول القرى والحصون ومسارات الانتقال بين الجبال وتهامة.\n\nتاريخ الاستقرار في ريمة مرتبط بالقرى الجبلية والزراعة والحصون ومسارات التواصل بين المرتفعات والسهول. ويجب عند توثيق المواقع التاريخية الفصل بين التقاليد المحلية وتواريخ المنشآت التي تثبتها مراجع متخصصة.","old_history":"تشكلت تجمعاتها التاريخية حول القرى والحصون ومسارات الانتقال بين الجبال وتهامة.","geography":"تغلب عليها الجبال شديدة الانحدار والأودية والمدرجات، مع أمطار موسمية ومناخ معتدل في المرتفعات.\n\nتمتاز بانحدارات حادة وأودية ومدرجات تسهم في تشكيل المشهد الزراعي. وتتفاوت الأمطار الموسمية والحرارة باختلاف الارتفاع واتجاه المنحدر، فلا يكفي تصويرها محافظة خضراء لتفسير وضع المياه على مدار العام.","old_geography":"تغلب عليها الجبال شديدة الانحدار والأودية والمدرجات، مع أمطار موسمية ومناخ معتدل في المرتفعات.","economy":"تعتمد بصورة رئيسية على الزراعة وتربية الماشية والأسواق والحرف المحلية.\n\nتستند أنشطة كثيرة إلى الزراعة وتربية الماشية والأسواق المحلية والحرف، مع اختلاف حجم كل نشاط بين المديريات. يتيح فهم التضاريس تفسير بعض صعوبات النقل دون تقديم أرقام عن الدخل أو الإنتاج من غير إحصاءات.","old_economy":"تعتمد بصورة رئيسية على الزراعة وتربية الماشية والأسواق والحرف المحلية.","landmarks":"الجبين، كسمة، الجعفرية، السلفية، مزهر والقرى والمدرجات الجبلية.\n\nيقدم الجبين وكسمة والجعفرية والسلفية ومزهر والقرى الجبلية خريطة للتنوع المحلي في المساحة الصغيرة نسبياً. ينبغي إضافة توثيق مستقل لأي مبنى تاريخي أو مزار محدد قبل وصف حالته أو استخدامه.","old_landmarks":"الجبين، كسمة، الجعفرية، السلفية، مزهر والقرى والمدرجات الجبلية."},{"id":"YE32","description":"أرخبيل يمني في المحيط الهندي يتميز بتنوع حيوي فريد ونباتات مستوطنة ومناظر طبيعية استثنائية.\n\nسقطرى أرخبيل يمني بعيد عن البر الرئيسي يتمتع بتنوع طبيعي وثقافي خاص، مع تجمعات سكانية على السواحل والداخل. تبرز فيه نباتات مستوطنة ومواقع طبيعية ذات أهمية عالمية، لكن تعريفه لا يختزل في شجرة دم الأخوين.","old_description":"أرخبيل يمني في المحيط الهندي يتميز بتنوع حيوي فريد ونباتات مستوطنة ومناظر طبيعية استثنائية.","history":"ارتبطت سقطرى منذ القدم بالملاحة والتجارة البحرية، وحافظ سكانها على لغة وتراث محلي مميزين.\n\nارتبط الأرخبيل بالملاحة والتجارة في المحيط الهندي، وله تراث لغوي محلي يتمثل في السقطرية. أدرجته اليونسكو موقعاً طبيعياً للتراث العالمي عام 2008 تقديراً لقيمته البيولوجية، وهو إدراج يختلف عن مواقع التراث العمراني.","old_history":"ارتبطت سقطرى منذ القدم بالملاحة والتجارة البحرية، وحافظ سكانها على لغة وتراث محلي مميزين.","geography":"تضم جبال حجهر وهضاباً وكهوفاً وشواطئ وبحيرات ساحلية، وتتأثر بموسمين للرياح الموسمية.\n\nتجمع البيئة جبال حجهر والهضاب والكهوف والسواحل والبحيرات الساحلية؛ وتتأثر مواسم الحركة والطقس بالرياح الموسمية. لذا تختلف ظروف الاستقرار والتنقل والغطاء النباتي بين أجزاء الأرخبيل وأوقات السنة.","old_geography":"تضم جبال حجهر وهضاباً وكهوفاً وشواطئ وبحيرات ساحلية، وتتأثر بموسمين للرياح الموسمية.","economy":"تعتمد الأنشطة على الصيد والرعي والسياحة البيئية والتجارة والخدمات المحلية.\n\nتستند سبل العيش المحلية إلى الصيد والرعي والتجارة وبعض الخدمات والسياحة البيئية. ولا يعني وجود الإمكانات السياحية أن البنية السياحية أو الرحلات متاحة في كل موسم، كما تحتاج الأنشطة الاقتصادية إلى مراعاة هشاشة البيئة.","old_economy":"تعتمد الأنشطة على الصيد والرعي والسياحة البيئية والتجارة والخدمات المحلية.","landmarks":"حديبو، جبال حجهر، محمية ديطوح، كهف حوق، قلنسية، شاطئ دليشة وأشجار دم الأخوين.\n\nتشكل جبال حجهر وقلنسية وديطوح وكهف حوق وحديبو والسواحل مواقع متباينة بين المناظر الطبيعية والاستقرار السكاني. يجب ربط أي وصف للنباتات والموائل بالمصادر البيئية المتخصصة وباعتبارات الحماية.","old_landmarks":"حديبو، جبال حجهر، محمية ديطوح، كهف حوق، قلنسية، شاطئ دليشة وأشجار دم الأخوين."}]'::jsonb) AS obj),
changed AS (
UPDATE public.governorates g SET
description=p.obj->>'description',
history=p.obj->>'history',
geography=p.obj->>'geography',
economy=p.obj->>'economy',
landmarks=p.obj->>'landmarks',
revision=g.revision+1,updated_at=now()
FROM input p WHERE g.id=p.obj->>'id' AND g.description=p.obj->>'old_description' AND g.history=p.obj->>'old_history' AND g.geography=p.obj->>'old_geography' AND g.economy=p.obj->>'old_economy' AND g.landmarks=p.obj->>'old_landmarks'
RETURNING g.id
) SELECT (SELECT count(*) FROM input) planned,(SELECT count(*) FROM changed) updated;